def evaluate(current_reputation, observation, my_history, round_num):
    # Adjust updates based on current reputation.
    if observation["action"] == "cooperate":
        # Cooperation gives less boost when reputation is already high.
        boost = 0.1 * (1 - current_reputation)
        return min(1.0, current_reputation + boost)
    else:
        # Defection penalty is stronger when reputation is high.
        penalty = 0.2 * (1 + current_reputation)
        return max(-1.0, current_reputation - penalty)

def decide(recipient_reputation, round_num, my_history):
    # Count own defections to adjust threshold.
    own_defs = sum(1 for a in my_history if a == 'defect')
    # Base threshold depends on own defection count (more defections -> less trusting).
    threshold = 0.2 if own_defs > 3 else 0.5
    # Become slightly more forgiving as rounds progress.
    threshold -= round_num * 0.01
    # Ensure threshold does not go below 0.0.
    return recipient_reputation > max(0.0, threshold)
